const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define a polygon representing the agricultural fields between the Kakhovka and North Crimean Canals in Ukraine.
  // This polygon is a simplification covering a significant agricultural area in the specified region.
  const geometry = ee.Geometry.Polygon(
    [[[33.72265005952924, 46.52182054655455],
      [34.11059082725385, 46.52554707101886],
      [34.10309193247846, 46.22591696230626],
      [33.69344400279096, 46.21639893962638],
      [33.72265005952924, 46.52182054655455]]]);

  const dateMayStart = '2023-05-10';
  const dateMayEnd = '2023-05-24'; // Centered around May 17
  const dateJuneStart = '2023-06-11';
  const dateJuneEnd = '2023-06-25'; // Centered around June 18

  const SCALE = 1000; // Use a larger scale for regional analysis to avoid memory issues and speed up.

  // Function to mask clouds in Sentinel-2 imagery
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000)
      .select(['B4', 'B8']) // Select Red and NIR bands
      .copyProperties(image, ['system:time_start']);
  }

  // Function to calculate NDVI
  function addNDVI(image) {
    return image.normalizedDifference(['B8', 'B4']).rename('NDVI');
  }

  // 2. Data Acquisition & Check for May
  let s2CollectionMay = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(dateMayStart, dateMayEnd)
    .filterBounds(geometry)
    .map(maskS2clouds)
    .map(addNDVI);

  const sizeMay = await s2CollectionMay.size().getInfo();
  if (sizeMay === 0) {
    console.log("C1: No Sentinel-2 images found for May period.");
    return;
  }
  console.log(`May Images (pre-cloud mask): ${sizeMay}`);

  // Create a mosaic and calculate mean NDVI for May
  const imageMay = s2CollectionMay.mean();

  // 3. Processing & Validation for May
  const countPixelsMay = await imageMay.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: SCALE,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (countPixelsMay === 0) {
    console.log("C2: No valid pixels for May after cloud masking.");
    return;
  }

  const meanNDVIMay = await imageMay.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: SCALE,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (meanNDVIMay === null || isNaN(meanNDVIMay)) {
    console.log("C3: Calculation failure for May NDVI.");
    return;
  }
  console.log(`May Mean NDVI: ${meanNDVIMay.toFixed(3)}, Valid Pixels: ${countPixelsMay}`);

  // 2. Data Acquisition & Check for June
  let s2CollectionJune = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(dateJuneStart, dateJuneEnd)
    .filterBounds(geometry)
    .map(maskS2clouds)
    .map(addNDVI);

  const sizeJune = await s2CollectionJune.size().getInfo();
  if (sizeJune === 0) {
    console.log("C1: No Sentinel-2 images found for June period.");
    return;
  }
  console.log(`June Images (pre-cloud mask): ${sizeJune}`);

  // Create a mosaic and calculate mean NDVI for June
  const imageJune = s2CollectionJune.mean();

  // 3. Processing & Validation for June
  const countPixelsJune = await imageJune.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: SCALE,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (countPixelsJune === 0) {
    console.log("C2: No valid pixels for June after cloud masking.");
    return;
  }

  const meanNDVIJune = await imageJune.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: SCALE,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (meanNDVIJune === null || isNaN(meanNDVIJune)) {
    console.log("C3: Calculation failure for June NDVI.");
    return;
  }
  console.log(`June Mean NDVI: ${meanNDVIJune.toFixed(3)}, Valid Pixels: ${countPixelsJune}`);

  // 5. Validation & Final Answer
  // 'Browner' implies lower NDVI.
  if (meanNDVIJune < meanNDVIMay) {
    console.log("A"); // Yes, fields were browner in June.
  } else {
    console.log("B"); // No, fields were not browner in June (or were greener/same).
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
